{
  "key": "pr-2241",
  "fields": {
    "summary": "gh-2237 [GOAL] Compaction basis collapse — trigger gate vs engine re-anchor measure different bases silent zero-pass auto-compact start loop (field S1 signature)",
    "description": "Closes #2237\nDevelopment changes."
  }
}

diff --git a/lib/src/agent/auto_compactor.dart b/lib/src/agent/auto_compactor.dart
index be94049e2e..f582cfc99c 100644
--- a/lib/src/agent/auto_compactor.dart
+++ b/lib/src/agent/auto_compactor.dart
@@ -29,6 +29,7 @@ import '../compaction/token_estimation.dart';
 import '../compaction/structured/engine.dart';
 import '../compaction/structured/markers.dart' show localTrimMarkerPrefix;
 import '../compaction/structured/judge.dart';
+import '../exceptions.dart' show CompactionErrorCode, CompactionException;
 import '../context.dart';
 import '../model.dart';
 import '../session/session_tree.dart' show Session;
@@ -161,7 +162,13 @@ abstract class AutoCompactorHooks {
   void onRetry(int attempt, int maxAttempts, Duration backoff, Object error);

   /// Called once after the loop terminates, on success or exhaustion.
-  void onDone(int passes, int tokens);
+  ///
+  /// gh-2237 AC2: [reason] carries the exit reason for a ZERO-pass
+  /// outcome — the deciding under-trigger gate and the basis/trigger
+  /// numbers (`basis N below trigger M at the <gate>`), so a started
+  /// compaction never ends in silence. Null when passes ran (the pass
+  /// receipts carry the story) or the engine did not name a reason.
+  void onDone(int passes, int tokens, {String? reason});

   /// Called when both smol and main failed in the same pass. The CLI
   /// prints a "switch models" hint here; the Flutter sheet shows a
@@ -807,6 +814,27 @@ final class AutoCompactor {
           summarizedMessages: summarized,
         );
       } catch (error) {
+        // gh-2237 (AC5): the gh-2044 empty-region refusal is a NO-WORK
+        // outcome, not a summarizer failure — the endpoint is healthy,
+        // there is simply nothing above the keep-recent cut to fold. It is
+        // deterministic (never retried) and must NOT arm the mechanical
+        // trim valve: the valve is the both-summarizers-DOWN rescue, and
+        // routing a healthy-endpoint no-region pass into it silently
+        // dropped the newest turn whenever projected checkpoint markers
+        // trailed it in the live context. The no-work terminal reports the
+        // honest no-op receipt instead; the host's settled verdict (passes
+        // ran + still over the trigger) surfaces the exhaustion story.
+        if (error is CompactionException &&
+            error.code == CompactionErrorCode.invalidSession) {
+          return _AttemptOutcome(
+            ok: true,
+            error: null,
+            noWork: true,
+            summary: null,
+            hiddenRecords: 0,
+            summarizedMessages: 0,
+          );
+        }
         final errorText = error.toString();
         final isTransient = _transient.hasMatch(errorText);
         // Issue #729 AC2: an overflow-classified failure is DETERMINISTIC —
@@ -1177,7 +1205,14 @@ class AutoCompactorFactory {
         // on every terminal path: hosts key off [AutoCompactorHooks.onDone]
         // (the CLI's HEP `compaction_end` frame, the Flutter chat sheet),
         // so a structured run that skips it leaves them open forever.
-        hooks.onDone(adapter.passCount, _requestTokens());
+        // gh-2237 AC2: a zero-pass outcome rides the engine's exit reason
+        // — the deciding gate and the basis/trigger numbers — so the
+        // host's terminal receipt can say why nothing ran.
+        hooks.onDone(
+          adapter.passCount,
+          _requestTokens(),
+          reason: adapter.passCount == 0 ? outcome.zeroPassReason : null,
+        );
         return true;
       }
       if (outcome.timedOut) {
@@ -1221,7 +1256,12 @@ class AutoCompactorFactory {
     return build().run();
   }

-  Future<({bool ok, bool timedOut, Object? error})> _runStructured({
+  /// gh-2237: [zeroPassReason] carries the engine's exit reason for an
+  /// unforced under-trigger run — the factory surfaces it through
+  /// [AutoCompactorHooks.onDone] so the zero-pass terminal receipt says
+  /// why nothing ran.
+  Future<({bool ok, bool timedOut, Object? error, String? zeroPassReason})>
+  _runStructured({
     _StructuredHooksAdapter? adapter,
     bool capTriggered = false,
   }) async {
@@ -1326,13 +1366,18 @@ class AutoCompactorFactory {
           throw timeout;
         },
       );
-      return (ok: ok, timedOut: false, error: null);
+      return (
+        ok: ok,
+        timedOut: false,
+        error: null,
+        zeroPassReason: compactor.zeroPassReason,
+      );
     } on TimeoutException catch (error) {
       // The engine run may settle later (the abort propagates
       // asynchronously); drop that late settle — the named failure here
       // is the authoritative outcome.
       running.ignore();
-      return (ok: false, timedOut: true, error: error);
+      return (ok: false, timedOut: true, error: error, zeroPassReason: null);
     }
   }

diff --git a/lib/src/cli/agent_cli_compaction.dart b/lib/src/cli/agent_cli_compaction.dart
